mapper.sql:
where del_flag = 0
and (opp_no like concat('%', #{keyword}, '%') or name like concat('%', #{keyword}, '%') or customer_name like concat('%', #{keyword}, '%') or owner like concat('%', #{keyword}, '%'))
and stage = #{stage}
and customer_id = #{customerId}

mapper.update:
update crm_opportunity
set del_flag  = 1,
    update_by = #{updateBy}
where id = #{id}
  and del_flag = 0
